CREATE TABLE v85012 (v85013 INT PRIMARY KEY, v85014 INT, v85015 VARCHAR(1)) AS SELECT EXTRACTVALUE(@xml, '/a/@b[contains(.,"1")]'), ST_ASTEXT(ST_GEOMFROMTEXT('MULTIPOINT(1 0,15 0,10 10)')), EXTRACTVALUE(@xml, '/a/b[string-length("x")=1]'), X('/ns:element', 'oö', 201902, '<a><or>test</or></a>', 'POINT(56 203)', 1, 'x'), BENCHMARK(NULL, 1 + 1), SOUNDEX(1), REGEXP_INSTR(x4, '[a-z]+', 385025119, 1, x5)